// orbit/prototype/tools/themes.py writes. Do not edit by hand: regenerate,
// and let test/orbit_tokens_test.dart check the two agree.
//
// Every field is one value the prototype's tokens.css defines. The names
// follow the CSS custom properties, camel-cased, so a screen reads
// `tokens.chatBg` where the prototype says `--chat-bg`.
part of 'orbit_tokens.dart';

